def dump_to_file(*output: str) -> str:
    """Dump `output` to a temporary file. Return path to the file."""
    fd, name = tempfile.mkstemp(prefix="blk_", suffix=".log", text=True)
    try:
        with os.fdopen(fd, "w", encoding="utf8") as f:
            for lines in output:
                f.write(lines)
                if lines and lines[-1] != "\n":
                    f.write("\n")
        return name
    except Exception:
        os.unlink(name)
        raise
